def pp(v):return f'{100*v:+.2f}'
def table(cols,rows):return '\n'.join(['| '+' | '.join(cols)+' |','|'+'|'.join(['---']*len(cols))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])
def main():
 d=pd.read_parquet(O/'classified_starts.parquet');a=pd.read_csv(O/'category_metrics.csv');e=pd.read_csv(O/'adjusted_associations.csv');s=pd.read_csv(O/'stable_metrics.csv',dtype={'trainer_id':str});q=pd.read_csv(O/'stable_model_support.csv',dtype={'trainer_id':str});p=pd.read_csv(O/'stable_destination_jockey_metrics.csv',dtype={'trainer_id':str,'jockey_id':str});l=pd.read_csv(O/'late_change_metrics.csv');ver=json.loads((O/'verification.json').read_text());audit=json.loads((O/'source_audit.json').read_text());assert ver['passed']
 primary=d[d.year.between(2024,2025)];g=primary[primary.main_eligible&primary.classification.eq('planned_as_card')];cats=a[a.window.eq('2024_2025')&a.meet.eq('전체')].set_index('category');up=cats.loc['ordinary_to_top'];ref=cats.loc['retained_ordinary'];eff=e[e.window.eq('2024_2025')&e.model.eq('primary')&e.term.eq('ordinary_to_top')].set_index('target');late_eff=e[e.window.eq('2024_2025')&e.model.eq('post_card_comparison')&e.term.eq('post_card_change')].set_index('target');st=e[e.model.eq('stable_joint')&e.target.eq('top3')].merge(q,on='term');st.to_csv(O/'stable_adjusted_top3.csv',index=False);raw=s[s.window.eq('2024_2025')&s.category.eq('ordinary_to_top')].sort_values(['n','meet','trainer_id'],ascending=[False,True,True]);pair=p[p.window.eq('2024_2025')&p.report_supported].sort_values(['n','meet','trainer_id','jockey_id'],ascending=[False,True,True,True]);late=l[l.window.eq('2024_2025')&l.population.eq('all_normal')&l.meet.eq('전체')];lateall=late[late.reason_class.eq('all')].iloc[0];positive=st[st.estimate.gt(0)&st.q.lt(.05)];negative=st[st.estimate.lt(0)&st.q.lt(.05)]
 summary=f"출전표 기준 계획교체만 남겨도 보통→상위 교체의 입상률 개선 연관성은 남았다. {int(up.n):,}출전 입상률 {percent(up.top3_rate)}, 보통유지 {int(ref.n):,}출전 {percent(ref.top3_rate)}. 같은말·경주와 과거상태 등을 통제한 차이 {pp(eff.loc['top3','estimate'])}%p(95% {pp(eff.loc['top3','ci_low'])}~{pp(eff.loc['top3','ci_high'])}, q={eff.loc['top3','q']:.4f}). 마방별 지원 {len(st)}곳의 양의 차이 중 BH q<.05는 {len(positive)}곳. 발표후 변경은 {int(lateall.n)}정상출전으로 따로 보았다."
 rawrows=[[r.meet,r.trainer_name,int(r.n),percent(r.previous_top3_rate),percent(r.top3_rate),pp(r.paired_top3_change)+'%p'] for r in raw.head(10).itertuples()]
 pairrows=[[r.meet,r.trainer_name,r.jockey_name,int(r.n),percent(r.previous_top3_rate),percent(r.top3_rate)] for r in pair.head(10).itertuples()]
 stable_rows=[]
 for r in st.sort_values(['meet','trainer_name']).itertuples():
  z=raw[raw.meet.eq(r.meet)&raw.trainer_id.eq(r.trainer_id)].iloc[0];base=s[s.window.eq('2024_2025')&s.meet.eq(r.meet)&s.trainer_id.eq(r.trainer_id)&s.category.eq('retained_ordinary')].iloc[0]
  stable_rows.append([r.meet,r.trainer_name,int(z.n),percent(z.top3_rate),int(base.n),percent(base.top3_rate),pp(r.estimate),f'{pp(r.ci_low)}~{pp(r.ci_high)}',f'{r.q:.4f}'])
 reason_names={'all':'전체','injury_fall':'부상·낙마','illness_pain':'질병·통증·컨디션','weight':'중량','other':'기타','unsupported':'사유 미지원'}
 laterows=[[reason_names[r.reason_class],int(r.n),percent(r.top3_rate),int(r.planned_switch_before_replacement)] for r in late.itertuples()]
 # Every normal post-card replacement grouped by actual historical stable; no selective listing in CSV.
 examples=primary[primary.classification.eq('post_card_change')&primary.reason.str.contains('4R 입장 중 낙마부상')][['date','meet','horse_name','trainer_name','scheduled_name','jockey_name','reason','raw_finish_rank']].head(3)
 exrows=[[r.date.strftime('%Y-%m-%d'),r.meet,r.horse_name,r.trainer_name,r.scheduled_name+'→'+r.jockey_name,r.reason,int(r.raw_finish_rank)] for r in examples.itertuples()]
 # Figure1: all stable estimates, not just favorable or significant rows.
 plot=st.sort_values(['meet','trainer_name']).reset_index(drop=True);fig,ax=plt.subplots(figsize=(10.5,13));y=np.arange(len(plot));ax.errorbar(plot.estimate*100,y,xerr=np.vstack([(plot.estimate-plot.ci_low)*100,(plot.ci_high-plot.estimate)*100]),fmt='o',color='#246a91',ecolor='#9bb7c9',capsize=2,markersize=4);ax.axvline(0,color='#555',lw=1);ax.set_yticks(y,[r.meet+' '+r.trainer_name for r in plot.itertuples()]);ax.invert_yaxis();ax.set_xlabel('계획 보통→상위 교체의 입상률 차이 (%p), 95% 군집구간');ax.set_title('마방별 차이: 같은 말·경주·과거상태 통제\n2024~2025, 지원 32개 마방 · 인과효과/승부의지 판정 아님',pad=15);ax.grid(axis='x',alpha=.2);fig.tight_layout();fig.savefig(F/'stable_adjusted_top3.png');plt.close(fig)
 fig,axes=plt.subplots(1,2,figsize=(11,4.7));labels=['계획 보통→상위','계획 보통 유지'];vals=[up.top3_rate*100,ref.top3_rate*100];bars=axes[0].bar(labels,vals,color=['#246a91','#9bb7c9']);axes[0].set_ylim(0,55);axes[0].set_ylabel('관측 입상률 (%)');axes[0].set_title('계획대로 기승한 비교표본');
 for b,v,num in zip(bars,vals,[up.n,ref.n]):axes[0].text(b.get_x()+b.get_width()/2,v+1,f'{v:.2f}%\nn={int(num):,}',ha='center')
 ls=late[~late.reason_class.eq('all')];bars=axes[1].bar([reason_names[v] for v in ls.reason_class],ls.n,color=['#437f99','#c1954e','#8e9c9d']);axes[1].set_ylim(0,560);axes[1].set_ylabel('정상출전 수');axes[1].set_title('출전표 발표 후 변경: 별도 분류')
 for b,r in zip(bars,ls.itertuples()):axes[1].text(b.get_x()+b.get_width()/2,r.n+8,f'n={int(r.n)}\n입상 {percent(r.top3_rate)}',ha='center')
